NSDictionary *TFAIBinaryExecute(NSString *identifier,NSDictionary *args,NSError **error){if(!Validate(args,error))return nil;if(args[@"binary_id"]&&![args[@"binary_id"] isEqual:identifier])return Fail(error,@"二进制标识不一致");if(!UUID(identifier))return Fail(error,@"二进制附件标识无效");NSString *dir=[Root() stringByAppendingPathComponent:identifier],*path=[dir stringByAppendingPathComponent:@"input.dylib"];for(NSString *p in @[Root(),dir,path])if([[[NSFileManager.defaultManager attributesOfItemAtPath:p error:nil] objectForKey:NSFileType] isEqual:NSFileTypeSymbolicLink])return Fail(error,@"二进制目录不接受链接");NSDictionary *meta=[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfFile:[dir stringByAppendingPathComponent:@"metadata.json"]]?:NSData.data options:0 error:nil];if(![meta isKindOfClass:NSDictionary.class]||![meta[@"sha256"] isKindOfClass:NSString.class])return Fail(error,@"二进制元数据损坏，请重新添加附件");NSDictionary *a=[NSFileManager.defaultManager attributesOfItemAtPath:path error:error];if(![a[NSFileType] isEqual:NSFileTypeRegular]||[a[NSFileSize] unsignedLongLongValue]>64*1024*1024)return Fail(error,@"本机二进制副本丢失或超出大小限制");NSData *d=[NSData dataWithContentsOfFile:path options:0 error:error];if(!d||![Digest(d) isEqual:meta[@"sha256"]])return Fail(error,@"二进制副本已变化，请重新添加附件");if([args[@"action"] isEqual:@"headers"]){@synchronized(NSClassFromString(@"NSFileManager")){NSString *docs=NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES).firstObject,*out=[docs stringByAppendingPathComponent:[@"ClassDump-" stringByAppendingString:identifier]];NSURL *cached=TFAIClassDumpExportURL(identifier);if(cached){NSData *info=[NSData dataWithContentsOfFile:[out stringByAppendingPathComponent:@"index.json"]];NSDictionary *index=info?[NSJSONSerialization JSONObjectWithData:info options:0 error:nil]:nil;if([index isKindOfClass:NSDictionary.class])return @{@"jobID":identifier,@"headers":index[@"headers"]?:@0,@"binaries":index[@"binaries"]?:@[],@"zipAvailable":@YES,@"note":@"复用同