NSArray *TFAIBinarySchemas(void){return @[@{@"name":@"binary_inspect",@"description":@"Analyze ONLY selected local dylib binary_id. Read-only LLVM MC ARM64 disassembly, Mach-O overview/encryption ranges, symbols, ASCII strings, windowed ARM64 branch facts including conditional/compare/test branches and unresolved indirect transfers. functions lists symbol/LC_FUNCTION_STARTS entries; cfg returns bounded candidate blocks/edges; xrefs scans direct code references to address with instruction pagination (4096 instructions per call). headers exports ObjC declarations locally and returns jobID. decode performs bounded base64/hex decoding or XOR with a supplied key at slice-relative file_offset/byte_count, returning hex/text; not image decryption or key recovery. Hex decodes ASCII hex TEXT stored in file, not arbitrary raw machine bytes. byte_count must exclude trailing NUL; file_offset is a slice-relative FILE offset, not a virtual address. key_hex is a known XOR key of 1-64 bytes; hex text/key accept whitespace-separated even-length tokens with optional 0x prefixes. On validation errors correct the identified input only with evidence; do not repeat identical calls or invent a key/encoding. No arbitrary paths, execution, image decryption or complete decompilation. offset is item offset except disassemble/branches where it is instruction offset from address. Use next_offset with same action/address/slice/query. Encrypted instruction ranges are rejected.",@"parameters":@{@"type":@"object",@"properties":@{@"binary_id":@{@"type":@"string"},@"action":@{@"type":@"string",@"enum":@[@"overview",@"symbols",@"strings",@"disassemble",@"branches",@"headers",@"decode",@"functions",@"cfg",@"xrefs"]},@"slice":@{@"type":@"integer",@"minimum":@0},@"address":@{@"type":@"string"},@"offset":@{@"type":@"integer",@"minimum":@0},@"limit":@{@"type":@"integer",@"minimum":@1,@"maximum":@200},@"query":@{@"type":@"string"},@"file_offset":@{@"type":@"integer",@"minimum":@0},@"byte_count":@{@"type":@"integer",@"minimum":@1,@"maximum":@8192},@"encoding":@{@"type":@"string",@"enum":@[@"base64",@"hex",@"xor"]},@"key_hex":@{@"type":@"string"}},@"required":@[@"binary_id",@"action"],@"additionalProperties":@NO}}];}

NSSet *TFAIBinarySelectedIDs(NSDictionary *references){NSMutableSet *ids=[NSMutableSet new];if(![references isKindOfClass:NSDictionary.class])return ids;for(id ref in references.allValues){if(![ref isKindOfClass:NSDictionary.class])continue;id value=ref[@"binaryInputID"];if(UUID(value))[ids addObject:value];}return ids;}

NSURL *TFAIBinaryInputURL(NSString *identifier,NSError **error){if(!TFAIBinaryExecute(identifier,@{@"action":@"overview"},error))return nil;return [NSURL fileURLWithPath:[[Root() stringByAppendingPathComponent:identifier] stringByAppendingPathComponent:@"input.dylib"]];}

