 NSDictionary *overview=TFAIBinaryExecute(identifier,@{@"action":@"overview",@"slice":@(slice)},error);if(!overview)return nil;
 if(![@[@"arm64",@"arm64e"] containsObject:overview[@"cpu"]])return Fail(error,@"逆向引擎入口仅支持 ARM64 / arm64e 切片");
 if([overview[@"encrypted"] boolValue])return Fail(error,@"所选切片含加密范围，不能交给反编译引擎");
 NSString *dir=[Root() stringByAppendingPathComponent:identifier];NSData *data=[NSData dataWithContentsOfFile:[dir stringByAppendingPathComponent:@"input.dylib"] options:0 error:error];NSDictionary *meta=[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfFile:[dir stringByAppendingPathComponent:@"metadata.json"]]?:NSData.data options:0 error:nil];
 if(!data||![Digest(data) isEqual:meta[@"sha256"]])return Fail(error,@"读取期间二进制副本已变化，请重新附加");
 NSData *thin=Slice(data,slice,error);if(!thin)return nil;NSString *path=[dir stringByAppendingPathComponent:[NSString stringWithFormat:@"analysis-slice-%lu.macho",(unsigned long)slice]];
 if([[[NSFileManager.defaultManager attributesOfItemAtPath:path error:nil] objectForKey:NSFileType] isEqual:NSFileTypeSymbolicLink])return Fail(error,@"切片缓存不接受链接");
 if(![thin writeToFile:path options:NSDataWritingAtomic error:error])return nil;return [NSURL fileURLWithPath:path];
}

NSArray *TFAIObfuscationSchemas(void){return @[@{@"name":@"binary_obfuscation_scan",@"description":@"Read-only evidence scan for a selected staged ARM64/arm64e Mach-O. Detects LC_ENCRYPTION_INFO, high-entropy data, indirect dispatcher-like control flow and abnormal conditional-branch density. Heuristic findings require CFG/disassembly or sandbox_reverse confirmation; it never executes code or recovers unknown keys.",@"parameters":@{@"type":@"object",@"properties":@{@"binary_id":@{@"type":@"string"},@"slice":@{@"type":@"integer",@"minimum":@0}},@"required":@[@"binary_id"],@"additionalProperties":@NO}}];}
